// نشست‌ها با راه‌اندازی مجدد سرور پاک نمی‌شوند.
class FileStore extends session.Store {
  constructor(file) {
    super();
    this.file = file; this.map = new Map(); this.timer = null;
    try { for (const [k, v] of Object.entries(JSON.parse(fs.readFileSync(file, 'utf8')))) this.map.set(k, v); } catch { /* فایل هنوز وجود ندارد */ }
    this.prune();
    setInterval(() => this.prune(), 60 * 60 * 1000).unref();
  }
  prune() { const now = Date.now(); for (const [k, v] of this.map) if (v.exp <= now) this.map.delete(k); this.save(); }
  save() { if (this.timer) return; this.timer = setTimeout(() => { this.timer = null; this.flush(); }, 500); this.timer.unref?.(); }
  flush() {
    try { const tmp = this.file + '.tmp'; fs.writeFileSync(tmp, JSON.stringify(Object.fromEntries(this.map))); fs.renameSync(tmp, this.file); }
    catch (e) { console.error('Session save failed:', e.message); }
  }
  get(sid, cb) { const e = this.map.get(sid); if (!e) return cb(null, null); if (e.exp <= Date.now()) { this.map.delete(sid); return cb(null, null); } try { cb(null, JSON.parse(e.data)); } catch (err) { cb(err); } }
  set(sid, sess, cb) {
    const exp = sess.cookie && sess.cookie.expires ? new Date(sess.cookie.expires).getTime() : Date.now() + 12 * 3600 * 1000;
    this.map.set(sid, { exp, data: JSON.stringify(sess) }); this.save(); cb && cb(null);
  }
  destroy(sid, cb) { this.map.delete(sid); this.save(); cb && cb(null); }
  touch(sid, sess, cb) { this.set(sid, sess, cb); }
}
