function calcStreak(days) {
  const set = new Set(days); const cur = new Date(); if (!set.has(fmtDay(cur))) cur.setDate(cur.getDate() - 1);
  let n = 0; while (set.has(fmtDay(cur))) { n++; cur.setDate(cur.getDate() - 1); } return n;
}
// حمله CSRF: درخواست‌های تغییردهنده از مبدأ دیگر رد می‌شوند.
app.use('/api', (req, res, next) => {
  if (['GET', 'HEAD', 'OPTIONS'].includes(req.method)) return next();
  const origin = req.get('origin'), site = req.get('sec-fetch-site');
  if ((origin && origin !== `${req.protocol}://${req.get('host')}`) || site === 'cross-site') return res.status(403).json({ error: 'درخواست با مبدأ نامعتبر رد شد.' });
  next();
});

