      const detail = String(d?.error?.message || '');
      if (r.status === 401) return { ...s, reachable: true, keyInvalid: true };
      if (r.status === 404) return { ...s, reachable: true, modelInstalled: false };
      if (r.status === 429) return { ...s, reachable: true, detail: 'سهمیه یا محدودیت درخواست' };
