      if (/location is not supported/i.test(detail)) return { ...s, reachable: true, locationBlocked: true };
      if (r.status === 404) return { ...s, reachable: true, modelInstalled: false };
      if (r.status === 429) return { ...s, reachable: true, detail: detail.slice(0, 200) };
      if (/api key not valid|api_key_invalid|api key expired/i.test(detail) || r.status === 401) return { ...s, reachable: true, keyInvalid: true, detail: detail.slice(0, 200) };
      if (r.status === 400 || r.status === 403) return { ...s, reachable: true, forbidden: true, detail: detail.slice(0, 200) };
