    if (/location is not supported/i.test(detail)) throw new Error('AI_LOCATION');
    if (response.status === 429) throw new Error('AI_RATE_LIMIT');
    if (response.status === 404) throw new Error('AI_MODEL_MISSING');
    if (response.status === 401 || /api key not valid|api_key_invalid|api key expired|invalid api key|incorrect api key/i.test(detail)) throw new Error('AI_BAD_KEY');
    if (response.status === 403 || response.status === 400) { const e = new Error('AI_FORBIDDEN'); e.detail = detail; throw e; }
