    AI_RATE_LIMIT: [429, 'سقف درخواست یا سهمیه‌ی سرویس هوش مصنوعی پر شده؛ کمی بعد دوباره امتحان کنید.'],
    AI_TIMEOUT: [504, 'پاسخ هوش مصنوعی بیش از حد طول کشید؛ پرسش را کوتاه‌تر کنید یا دوباره تلاش کنید.'],
    AI_UNREACHABLE: [502, prov === 'ollama' ? 'به Ollama وصل نشد. مطمئن شوید برنامه Ollama در حال اجراست.' : 'اتصال سرور به سرویس هوش مصنوعی برقرار نشد (اینترنت، فایروال یا فیلترشکن را بررسی کنید؛ سرور Node از تنظیمات پروکسی مرورگر استفاده نمی‌کند).'],
    AI_MODEL_MISSING: [502, prov === 'ollama' ? `مدل ${model} روی Ollama نصب نیست. دستور «ollama pull ${model}» را اجرا کنید.` : `مدل «${model}» در دسترس نیست (احتمالاً قدیمی یا حذف شده). در فایل .env مقدار ${envName} را به مدل فعلی تغییر دهید${prov === 'gemini' ? ' (مثلاً gemini-3.8-flash)' : ''} و سرور را دوباره اجرا کنید.`],
    AI_BAD_KEY: [502, prov === 'openai' ? 'OpenAI کلید API را نپذیرفت؛ مقدار OPENAI_API_KEY را در فایل .env بررسی کنید و از فعال بودن دسترسی API مطمئن شوید.' : 'گوگل می‌گوید کلید نامعتبر است. کلید را دوباره از Google AI Studio کپی کنید (کامل، بدون فاصله/کوتیشن، فقط در یک خط GEMINI_API_KEY=...) و سرور را دوباره اجرا کنید.'],
    AI_FORBIDDEN: [502, prov === 'openai' ? 'OpenAI درخواست را رد کرد؛ دسترسی پروژه، مجوز مدل و محدودیت‌های حساب API را بررسی کنید.' : 'گوگل کلید را شناخته ولی اجازه‌ی استفاده نداده است (ممکن است مدل برای این پروژه/حساب فعال نباشد، API روی پروژه فعال نباشد، یا کلید محدودیت داشته باشد). یک مدل دیگر را امتحان کنید و در کنسول ارائه‌دهنده وضعیت کلید و پروژه را ببینید.'],
    AI_LOCATION: [502, 'سرویس Gemini از موقعیت/IP فعلی شما پشتیبانی نمی‌کند. می‌توانید ارائه‌دهنده را به Groq/OpenRouter یا Ollama تغییر دهید.'],
    AI_EMPTY_RESPONSE: [502, 'مدل پاسخی تولید نکرد (ممکن است فیلتر ایمنی یا سقف طول پاسخ باعث شده باشد). پرسش را به شکل دیگری بنویسید.']
