function normalizeAIQuestion(q) {
  if (!q || typeof q !== 'object') return null;
  const prompt = text(String(q.prompt || ''), 1500);
  const options = Array.isArray(q.options) ? q.options.map(x => text(String(x), 300)).filter(Boolean) : [];
  if (prompt.length < 3 || options.length !== 4 || new Set(options).size !== 4) return null;
  let correct = text(String(q.correct_answer ?? ''), 500);
  if (!options.includes(correct)) {
    // مدل‌ها گاهی به‌جای متن گزینه، حرف یا شماره آن را برمی‌گردانند.
    const byLabel = { 'الف': 0, 'ب': 1, 'پ': 2, 'ج': 2, 'ت': 3, 'د': 3, a: 0, b: 1, c: 2, d: 3, '1': 0, '2': 1, '3': 2, '4': 3 };
    const idx = byLabel[correct.toLowerCase()];
    if (idx === undefined) return null;
    correct = options[idx];
  }
  return { prompt, options, correct_answer: correct, explanation: text(String(q.explanation || ''), 1000) };
}
app.post('/api/ai/generate-questions', requireAuth, requireRole('teacher', 'admin'), aiLimiter, async (req, res) => {
  const context = text(req.body.context, 4000), count = Math.min(10, Math.max(1, Number(req.body.count) || 5));
  if (context.length < 20) return res.status(400).json({ error: 'برای ساخت سؤال، متن درس یا نکته‌ها را (حداقل چند جمله) وارد کنید.' });
  try {
    const prompt = `برای متن زیر ${count} سؤال چندگزینه‌ای آموزشی بساز. فقط JSON معتبر و بدون markdown با این قالب بده: {"questions":[{"prompt":"...","options":["الف","ب","پ","ت"],"correct_answer":"یکی از گزینه‌ها دقیقاً","explanation":"..."}]}\nمتن: ${context}`;
    const raw = await askAI(prompt, 'تو طراح سؤال ادبیات فارسی هستی. سؤال‌ها باید از متن داده‌شده باشند و پاسخ درست روشن داشته باشند. فقط JSON بده.');
    const s = raw.indexOf('{'), e = raw.lastIndexOf('}');
    const parsed = JSON.parse(s >= 0 && e > s ? raw.slice(s, e + 1) : raw);
    const list = (Array.isArray(parsed.questions) ? parsed.questions : []).map(normalizeAIQuestion).filter(Boolean).slice(0, count);
    if (!list.length) throw new Error('BAD_JSON');
    res.json({ questions: list });
  } catch (e) {
    if (String(e.message).startsWith('AI_')) { const [status, error] = aiError(e); return res.status(status).json({ error }); }
    res.status(502).json({ error: 'خروجی هوش مصنوعی قابل استفاده نبود (مدل‌های کوچک گاهی JSON درست نمی‌دهند). متن را کوتاه‌تر کنید یا دوباره امتحان کنید.' });
  }
});

