const DUMMY_HASH = bcrypt.hashSync('not-a-real-password', 12);
function startSession(req, res, userId, status = 200) {
  req.session.regenerate(err => {
    if (err) return res.status(500).json({ error: 'ورود ممکن نشد.' });
    req.session.userId = userId;
    res.status(status).json({ user: safeUser(db.prepare('SELECT id,name,email,role,created_at FROM users WHERE id=?').get(userId)) });
  });
}
app.get('/api/auth/me', (req, res) => {
  if (!req.session.userId) return res.json({ user: null });
  const u = db.prepare('SELECT id,name,email,role,active,created_at FROM users WHERE id=?').get(req.session.userId);
  res.json({ user: u && u.active ? safeUser(u) : null });
});
app.post('/api/auth/register', (req, res) => {
  const name = text(req.body.name, 80), email = text(req.body.email, 160).toLowerCase(), password = String(req.body.password || '');
  if (name.length < 2 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) || password.length < 10 || password.length > 128) return res.status(400).json({ error: 'نام، ایمیل معتبر و گذرواژه‌ای با حداقل ۱۰ نویسه وارد کنید.' });
  try {
    const info = db.prepare('INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,?)').run(name, email, bcrypt.hashSync(password, 12), 'student');
    startSession(req, res, info.lastInsertRowid, 201);
  } catch (e) { if (isUnique(e)) return res.status(409).json({ error: 'این ایمیل قبلاً ثبت شده است.' }); throw e; }
});
app.post('/api/auth/login', (req, res) => {
  const email = text(req.body.email, 160).toLowerCase(), password = String(req.body.password || '');
  const u = db.prepare('SELECT * FROM users WHERE email=?').get(email);
  const ok = bcrypt.compareSync(password, u ? u.password_hash : DUMMY_HASH);   // زمان پاسخ برای ایمیل ناموجود هم یکسان است
  if (!u || !u.active || !ok) return res.status(401).json({ error: 'ایمیل یا گذرواژه درست نیست.' });
  startSession(req, res, u.id);
});
app.post('/api/auth/logout', (req, res) => req.session.destroy(() => { res.clearCookie('adabiyar.sid'); res.json({ ok: true }); }));
app.post('/api/auth/password', requireAuth, (req, res) => {
  const cur = String(req.body.current || ''), next = String(req.body.next || '');
  const row = db.prepare('SELECT password_hash FROM users WHERE id=?').get(req.user.id);
  if (!bcrypt.compareSync(cur, row.password_hash)) return res.status(400).json({ error: 'گذرواژه فعلی درست نیست.' });
  if (next.length < 10 || next.length > 128) return res.status(400).json({ error: 'گذرواژه جدید باید ۱۰ تا ۱۲۸ نویسه باشد.' });
  db.prepare('UPDATE users SET password_hash=? WHERE id=?').run(bcrypt.hashSync(next, 12), req.user.id);
  res.json({ ok: true });
});
app.patch('/api/auth/profile', requireAuth, (req, res) => {
  const name = text(req.body.name, 80);
  if (name.length < 2) return res.status(400).json({ error: 'نام باید حداقل ۲ نویسه باشد.' });
  db.prepare('UPDATE users SET name=? WHERE id=?').run(name, req.user.id);
  res.json({ user: safeUser({ ...req.user, name }) });
});

