const lessonCols = 'id,grade,title,slug,summary,important_points,vocabulary,content_status,source_note';
const shapeLesson = l => ({ ...l, important_points: parseJSON(l.important_points), vocabulary: parseJSON(l.vocabulary) });
const shapePoem = p => ({ ...p, literary_notes: parseJSON(p.literary_notes), grammar_notes: parseJSON(p.grammar_notes) });
const validGrade = g => Number.isInteger(g) && g >= 7 && g <= 12;
app.get('/api/grades', (req, res) => res.json({ grades: [7, 8, 9, 10, 11, 12] }));
app.get('/api/lessons', (req, res) => {
  const grade = Number(req.query.grade), q = text(req.query.q, 100), where = [], args = [];
  if (validGrade(grade)) { where.push('grade=?'); args.push(grade); }
  if (q) { where.push("(title LIKE ? ESCAPE '\\' OR summary LIKE ? ESCAPE '\\')"); args.push(like(q), like(q)); }
  const rows = db.prepare(`SELECT ${lessonCols} FROM lessons ${where.length ? 'WHERE ' + where.join(' AND ') : ''} ORDER BY grade,id`).all(...args);
  res.json({ lessons: rows.map(shapeLesson) });
});
app.get('/api/poems/daily', (req, res) => {
  const rows = db.prepare('SELECT * FROM poems ORDER BY id').all();
  if (!rows.length) return res.json({ poem: null });
  const d = new Date(), dayNum = Math.floor(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()) / 86400000);
  const p = shapePoem(rows[dayNum % rows.length]);
  res.json({ poem: { id: p.id, title: p.title, poet: p.poet, grade: p.grade, verse: String(p.text).split('\n').filter(Boolean).slice(0, 2).join('\n') } });
});
app.get('/api/poems', (req, res) => {
  const grade = Number(req.query.grade), q = text(req.query.q, 100), where = [], args = [];
  if (validGrade(grade)) { where.push('grade=?'); args.push(grade); }
  if (q) { where.push("(title LIKE ? ESCAPE '\\' OR poet LIKE ? ESCAPE '\\' OR text LIKE ? ESCAPE '\\')"); args.push(like(q), like(q), like(q)); }
  res.json({ poems: db.prepare(`SELECT * FROM poems ${where.length ? 'WHERE ' + where.join(' AND ') : ''} ORDER BY grade,id`).all(...args).map(shapePoem) });
});

