// ───────────────────────── آزمون‌ها ─────────────────────────
const GRACE_MS = 20000;   // مهلت کوتاه برای تأخیر شبکه هنگام ارسال نهایی
const attemptDeadline = a => {   // a باید duration_minutes و ends_at آزمون را هم داشته باشد
  let end = sqlTime(a.started_at) + a.duration_minutes * 60000; const e = userTime(a.ends_at);
  return e !== null ? Math.min(end, e) : end;
};
const UPSERT_GRADED = 'INSERT INTO answers(attempt_id,question_id,answer_text,is_correct,awarded_points) VALUES(?,?,?,?,?) ON CONFLICT(attempt_id,question_id) DO UPDATE SET answer_text=excluded.answer_text,is_correct=excluded.is_correct,awarded_points=excluded.awarded_points';
function gradeAttempt(attempt, submitted) {   // submitted=null یعنی فقط پاسخ‌های ذخیره‌شده خودکار
  const questions = db.prepare('SELECT * FROM questions WHERE exam_id=?').all(attempt.exam_id);
  const saved = new Map(db.prepare('SELECT question_id,answer_text FROM answers WHERE attempt_id=?').all(attempt.id).map(r => [r.question_id, r.answer_text]));
  const given = new Map();
  if (Array.isArray(submitted)) for (const it of submitted) if (it && Number.isInteger(Number(it.question_id))) given.set(Number(it.question_id), text(it.answer, 3000));
  let score = 0;
  db.transaction(() => {
    for (const q of questions) {
      const value = given.has(q.id) ? given.get(q.id) : (saved.get(q.id) || '');
      const correct = q.type === 'mcq' ? value === q.correct_answer : null, awarded = correct ? q.points : 0;
      score += awarded;
      db.prepare(UPSERT_GRADED).run(attempt.id, q.id, value, correct === null ? null : (correct ? 1 : 0), awarded);
    }
    db.prepare("UPDATE attempts SET status='submitted',score=?,submitted_at=CURRENT_TIMESTAMP WHERE id=?").run(score, attempt.id);
  })();
  return score;
}
// آزمون‌هایی که زمانشان تمام شده و دانش‌آموز ارسال نکرده، با پاسخ‌های ذخیره‌شده تصحیح می‌شوند.
function finalizeExpired() {
  const rows = db.prepare("SELECT a.*,e.duration_minutes,e.ends_at FROM attempts a JOIN exams e ON e.id=a.exam_id WHERE a.status='in_progress'").all();
  const now = Date.now();
  for (const a of rows) if (now > attemptDeadline(a) + GRACE_MS) gradeAttempt(a, null);
}
function ownsExam(examId, user) {
  const e = db.prepare('SELECT * FROM exams WHERE id=?').get(examId);
  return e && (user.role === 'admin' || e.teacher_id === user.id) ? e : null;
}
function parseExam(b) {
  const title = text(b.title, 160), description = text(b.description, 1000), grade = Number(b.grade), duration = Number(b.duration_minutes || 30);
  const starts = text(b.starts_at, 40) || null, ends = text(b.ends_at, 40) || null;
  if (title.length < 3 || !validGrade(grade) || !(duration >= 1 && duration <= 240)) return { error: 'عنوان، پایه ۷ تا ۱۲ و زمان ۱ تا ۲۴۰ دقیقه لازم است.' };
  if ((starts && userTime(starts) === null) || (ends && userTime(ends) === null)) return { error: 'تاریخ شروع یا پایان معتبر نیست.' };
  if (starts && ends && userTime(ends) <= userTime(starts)) return { error: 'پایان آزمون باید بعد از شروع آن باشد.' };
  return { value: { title, description, grade, duration: Math.round(duration), starts, ends, review: b.review_answers === false ? 0 : 1 } };
}
function parseQuestion(b) {
  const prompt = text(b.prompt, 1500), options = Array.isArray(b.options) ? b.options.map(x => text(x, 300)).filter(Boolean).slice(0, 6) : [];
  const correct = text(b.correct_answer, 500), points = Math.min(100, Math.max(0.25, Number(b.points) || 1));
  if (b.type === 'short') {   // سؤال تشریحی: بدون گزینه؛ «correct_answer» به‌عنوان پاسخ نمونه/بارم‌بندی برای معلم نگه داشته می‌شود
    if (prompt.length < 3) return { error: 'صورت سؤال تشریحی را بنویسید.' };
    return { value: { type: 'short', prompt, options: [], correct: text(b.model_answer || b.correct_answer, 3000), points, explanation: text(b.explanation, 1000), lessonId: null } };
  }
  if (prompt.length < 3 || options.length !== 4 || new Set(options).size !== 4 || !options.includes(correct)) return { error: 'هر سؤال تستی باید دقیقاً چهار گزینه متفاوت و یک پاسخ صحیح از بین همان گزینه‌ها داشته باشد.' };
  const lesson = b.lesson_id ? db.prepare('SELECT id FROM lessons WHERE id=?').get(Number(b.lesson_id)) : null;
  return { value: { type: 'mcq', prompt, options, correct, points, explanation: text(b.explanation, 1000), lessonId: lesson ? lesson.id : null } };
}
