app.get('/api/exams/:id/stats', ...requireTeacher, (req, res) => {
  finalizeExpired();
  const exam = ownsExam(Number(req.params.id), req.user); if (!exam) return res.status(404).json({ error: 'آزمون پیدا نشد یا اجازه ندارید.' });
  const agg = db.prepare("SELECT COUNT(*) n, AVG(score) avg, MIN(score) min, MAX(score) max FROM attempts WHERE exam_id=? AND status IN ('submitted','graded')").get(exam.id);
  const max = db.prepare('SELECT COALESCE(SUM(points),0) n FROM questions WHERE exam_id=?').get(exam.id).n;
  const perQ = db.prepare("SELECT q.id,q.prompt,COUNT(an.id) answered,COALESCE(SUM(CASE WHEN an.is_correct=1 THEN 1 ELSE 0 END),0) correct FROM questions q LEFT JOIN answers an ON an.question_id=q.id AND an.attempt_id IN (SELECT id FROM attempts WHERE exam_id=? AND status IN ('submitted','graded')) WHERE q.exam_id=? GROUP BY q.id ORDER BY q.id").all(exam.id, exam.id);
  const inProgress = db.prepare("SELECT COUNT(*) n FROM attempts WHERE exam_id=? AND status='in_progress'").get(exam.id).n;
  res.json({ finished: agg.n, in_progress: inProgress, average: agg.avg === null ? null : Math.round(agg.avg * 100) / 100, min: agg.min, max: agg.max, max_score: max, questions: perQ.map(q => ({ ...q, percent: q.answered ? Math.round(q.correct / q.answered * 100) : null })) });
});
app.get('/api/exams/:id', requireAuth, (req, res) => {
  const e = db.prepare('SELECT id,title,description,grade,duration_minutes,starts_at,ends_at,review_answers,status,teacher_id FROM exams WHERE id=?').get(Number(req.params.id));
  const isStudent = req.user.role === 'student';
  if (!e || (isStudent && e.status !== 'published') || (req.user.role === 'teacher' && e.teacher_id !== req.user.id)) return res.status(404).json({ error: 'آزمون پیدا نشد یا اجازه ندارید.' });
  const { teacher_id, ...exam } = e;
  const qs = db.prepare('SELECT id,prompt,type,options,points,correct_answer,explanation FROM questions WHERE exam_id=? ORDER BY id').all(e.id);
  // دانش‌آموز پیش از شروع آزمون سؤال‌ها را نمی‌بیند؛ سؤال‌ها فقط از مسیر start می‌آیند.
  if (isStudent) return res.json({ exam, question_count: qs.length, questions: [] });
  res.json({ exam, question_count: qs.length, questions: qs.map(q => ({ ...q, options: parseJSON(q.options) })) });
});
app.post('/api/exams/:id/start', requireAuth, requireRole('student'), (req, res) => {
  finalizeExpired();
  const exam = db.prepare("SELECT * FROM exams WHERE id=? AND status='published'").get(Number(req.params.id));
  if (!exam) return res.status(404).json({ error: 'آزمون منتشرشده‌ای با این شناسه پیدا نشد.' });
  const now = Date.now(), st = userTime(exam.starts_at), en = userTime(exam.ends_at);
  let attempt = db.prepare('SELECT * FROM attempts WHERE exam_id=? AND student_id=?').get(exam.id, req.user.id);
  if (attempt && attempt.status !== 'in_progress') return res.status(409).json({ error: 'در این نسخه برای هر دانش‌آموز یک تلاش ثبت می‌شود و تلاش تو قبلاً تمام شده است.' });
  if (!attempt) {
    if (st !== null && now < st) return res.status(403).json({ error: 'زمان شروع آزمون هنوز نرسیده است.' });
    if (en !== null && now > en) return res.status(403).json({ error: 'مهلت آزمون به پایان رسیده است.' });
    const max = db.prepare('SELECT COALESCE(SUM(points),0) n FROM questions WHERE exam_id=?').get(exam.id).n;
    const info = db.prepare('INSERT INTO attempts(exam_id,student_id,max_score) VALUES(?,?,?)').run(exam.id, req.user.id, max);
    attempt = db.prepare('SELECT * FROM attempts WHERE id=?').get(info.lastInsertRowid);
  }
  const remaining = Math.max(0, Math.floor((attemptDeadline({ ...attempt, duration_minutes: exam.duration_minutes, ends_at: exam.ends_at }) - now) / 1000));
  if (remaining <= 0) { gradeAttempt(attempt, null); return res.status(409).json({ error: 'زمان این آزمون تمام شده و پاسخ‌های ذخیره‌شده‌ات ثبت شد.' }); }
  const saved = {}; for (const r of db.prepare('SELECT question_id,answer_text FROM answers WHERE attempt_id=?').all(attempt.id)) saved[r.question_id] = r.answer_text;
  res.json({ attempt, duration_minutes: exam.duration_minutes, remaining_seconds: remaining, saved, questions: db.prepare('SELECT id,prompt,type,options,points FROM questions WHERE exam_id=? ORDER BY id').all(exam.id).map(q => ({ ...q, options: parseJSON(q.options) })) });
});
const loadOwnAttempt = (id, studentId) => db.prepare('SELECT a.*,e.duration_minutes,e.ends_at,e.review_answers FROM attempts a JOIN exams e ON e.id=a.exam_id WHERE a.id=? AND a.student_id=?').get(id, studentId);
app.put('/api/attempts/:id/answers', requireAuth, requireRole('student'), (req, res) => {
  const a = loadOwnAttempt(Number(req.params.id), req.user.id);
  if (!a) return res.status(404).json({ error: 'تلاش آزمون پیدا نشد.' });
  if (a.status !== 'in_progress') return res.status(409).json({ error: 'این آزمون قبلاً ارسال شده است.' });
  if (Date.now() > attemptDeadline(a) + GRACE_MS) { gradeAttempt(a, null); return res.status(409).json({ error: 'زمان آزمون تمام شده است.' }); }
  const qids = new Set(db.prepare('SELECT id FROM questions WHERE exam_id=?').all(a.exam_id).map(q => q.id));
  const items = Array.isArray(req.body.answers) ? req.body.answers.slice(0, 500) : [];
  db.transaction(() => {
    for (const it of items) {
      const qid = Number(it && it.question_id); if (!qids.has(qid)) continue;
      db.prepare('INSERT INTO answers(attempt_id,question_id,answer_text) VALUES(?,?,?) ON CONFLICT(attempt_id,question_id) DO UPDATE SET answer_text=excluded.answer_text').run(a.id, qid, text(it.answer, 3000));
    }
  })();
  res.json({ ok: true });
});
app.post('/api/attempts/:id/submit', requireAuth, requireRole('student'), (req, res) => {
  const a = loadOwnAttempt(Number(req.params.id), req.user.id);
  if (!a) return res.status(404).json({ error: 'تلاش آزمون پیدا نشد.' });
  if (a.status !== 'in_progress') return res.status(409).json({ error: 'این آزمون قبلاً ارسال شده است.' });
  const late = Date.now() > attemptDeadline(a) + GRACE_MS;   // دیرکرد: فقط پاسخ‌های ذخیره‌شده خودکار حساب می‌شود
  const score = gradeAttempt(a, late ? null : req.body.answers);
  touchActivity(req.user.id);
  res.json({ ok: true, score, max_score: a.max_score, review_allowed: !!a.review_answers, late, attempt_id: a.id });
});
