app.get('/api/teacher/submissions.csv', ...requireTeacher, (req, res) => {
  finalizeExpired();
  const examId = Number(req.query.exam_id) || null, rows = listSubmissions(req.user).filter(r => !examId || r.exam_id === examId);
  const cell = v => { let s = String(v ?? ''); if (/^[=+\-@\t\r]/.test(s)) s = "'" + s; return '"' + s.replace(/"/g, '""') + '"'; };   // جلوگیری از تزریق فرمول در Excel
  const statusFa = { in_progress: 'در حال انجام', submitted: 'ارسال‌شده', graded: 'بررسی‌شده' };
  const lines = [['دانش‌آموز', 'ایمیل', 'آزمون', 'پایه', 'نمره', 'از', 'وضعیت', 'زمان ارسال'], ...rows.map(r => [r.student_name, r.email, r.title, r.grade, r.score ?? '', r.max_score, statusFa[r.status] || r.status, r.submitted_at || ''])];
  res.setHeader('Content-Type', 'text/csv; charset=utf-8'); res.setHeader('Content-Disposition', 'attachment; filename="adabiyar-results.csv"');
  res.send('\uFEFF' + lines.map(l => l.map(cell).join(',')).join('\r\n'));
});
app.post('/api/attempts/:id/grade', ...requireTeacher, (req, res) => {
  const a = db.prepare('SELECT a.*,e.teacher_id FROM attempts a JOIN exams e ON e.id=a.exam_id WHERE a.id=?').get(Number(req.params.id));
  if (!a || (req.user.role !== 'admin' && a.teacher_id !== req.user.id)) return res.status(404).json({ error: 'تلاش پیدا نشد یا اجازه ندارید.' });
  if (a.status === 'in_progress') return res.status(409).json({ error: 'این آزمون هنوز در حال انجام است.' });
  const grades = Array.isArray(req.body.answers) ? req.body.answers : [];
  db.transaction(() => {
    for (const g of grades) {
      const q = db.prepare('SELECT points FROM questions WHERE id=? AND exam_id=?').get(Number(g.question_id), a.exam_id); if (!q) continue;
      db.prepare('UPDATE answers SET awarded_points=?,teacher_feedback=? WHERE attempt_id=? AND question_id=?').run(Math.max(0, Math.min(q.points, Number(g.awarded_points) || 0)), text(g.feedback, 1000), a.id, Number(g.question_id));
    }
    db.prepare("UPDATE attempts SET score=?,status='graded' WHERE id=?").run(db.prepare('SELECT COALESCE(SUM(awarded_points),0) n FROM answers WHERE attempt_id=?').get(a.id).n, a.id);
  })();
  res.json({ ok: true });
});

