const parseArch = b => { const name = text(b.name, 120); if (name.length < 2) return { error: 'نام بنا لازم است.' }; if (photoField(b.photo, 300000) === false) return { error: 'عکس نامعتبر است یا از حد مجاز بزرگ‌تر است؛ عکس دیگری انتخاب کنید.' }; return { v: { name, sort: Number.isFinite(Number(b.sort)) ? Number(b.sort) : 999, subtitle: text(b.subtitle, 200), body: text(b.body, 4000), facts: text(b.facts, 300), photo: photoField(b.photo, 300000) } }; };
