function parsePoet(b) {
  const name = text(b.name, 120), century = Number(b.century);
  const poems = (Array.isArray(b.poems) ? b.poems : []).slice(0, 60).map(p => ({ title: text(p && p.title, 180), text: text(p && p.text, 6000) })).filter(p => p.text.length >= 2);
  if (name.length < 2 || !Number.isInteger(century) || century < 1 || century > 15) return { error: 'نام شاعر و قرن (۱ تا ۱۵) لازم است.' };
  const photo = photoField(b.photo, 130000); if (photo === false) return { error: 'عکس نامعتبر است یا از حد مجاز بزرگ‌تر است؛ عکس دیگری انتخاب کنید.' };
  return { v: { name, century, years: text(b.years, 80), title: text(b.title, 120), bio: text(b.bio, 12000), poems: JSON.stringify(poems), photo } };
}
const poetRow = r => ({ ...r, poems: parseJSON(r.poems) });
