const adminOnly = (req, res, next) => {
  const u = req.session && req.session.userId ? db.prepare('SELECT role,active FROM users WHERE id=?').get(req.session.userId) : null;
  if (u && u.active && u.role === 'admin') { res.set('Cache-Control', 'no-store'); return next(); }
  res.redirect('/');
};
