(() => {
  const p = (process.env.AI_PROVIDER || 'off').toLowerCase();
  if (p === 'gemini') {
    const k = geminiKey(), raw = String(process.env.GEMINI_API_KEY || '');
    if (!k) console.warn('⚠ AI_PROVIDER=gemini است ولی GEMINI_API_KEY خالی است. فایل .env باید کنار package.json باشد.');
    else {
      console.log(`Gemini: مدل ${geminiModel()} | کلید خوانده شد (${k.length} نویسه، شروع ${k.slice(0, 4)}…)`);
      if (raw !== k) console.warn('⚠ کلید فاصله یا کوتیشن اضافه داشت؛ خودکار پاک شد، ولی بهتر است در .env اصلاح شود.');
      if (/[^\x21-\x7E]/.test(k)) console.warn('⚠ کلید نویسه‌ی غیرمجاز (مثلاً فارسی یا فاصله) دارد؛ احتمالاً متن نمونه‌ی .env هنوز عوض نشده است.');
      else if (!k.startsWith('AIza')) console.warn('⚠ کلیدهای Google AI Studio معمولاً با AIza شروع می‌شوند؛ مطمئن شوید کلید درست را کپی کرده‌اید.');
    }
  }
})();
